// ---------------------------------------------------------------------------
// AI Recommendation Engine — statistical anthropometric model
// Based on CDC/WHO body proportion data
// ---------------------------------------------------------------------------

export interface RecommendInput {
  height: number; // cm
  weight: number; // kg
  gender: "male" | "female";
  bodyType: "slim" | "regular" | "athletic" | "plus";
  chartData: { headers: string[]; rows: Record<string, string>[] };
}

export interface RecommendResult {
  recommendedSize: string;
  confidence: number; // 0–100
  alternatives: { size: string; confidence: number }[];
  estimatedMeasurements: Record<string, number>;
}

// ---------------------------------------------------------------------------
// Anthropometric proportion tables (CDC/WHO-based)
// Values represent the coefficient of height used to estimate each measurement
// at a reference BMI of 22. Actual values are adjusted by BMI and body type.
// ---------------------------------------------------------------------------

interface ProportionTable {
  chestBase: number; // chest / height at BMI 22
  waistBase: number; // waist / height at BMI 22
  hipsBase: number; // hips / height at BMI 22
  shoulderBase: number; // shoulder width / height at BMI 22
  armLengthBase: number; // arm length / height at BMI 22
  inseamBase: number; // inseam / height at BMI 22
  bmiFactor: number; // cm added per BMI unit above/below 22
}

const PROPORTIONS: Record<"male" | "female", ProportionTable> = {
  male: {
    chestBase: 0.530,
    waistBase: 0.435,
    hipsBase: 0.510,
    shoulderBase: 0.245,
    armLengthBase: 0.330,
    inseamBase: 0.455,
    bmiFactor: 0.85,
  },
  female: {
    chestBase: 0.510,
    waistBase: 0.390,
    hipsBase: 0.540,
    shoulderBase: 0.225,
    armLengthBase: 0.305,
    inseamBase: 0.445,
    bmiFactor: 0.75,
  },
};

// ---------------------------------------------------------------------------
// Body-type adjustment multipliers applied to estimated measurements
// ---------------------------------------------------------------------------

interface BodyTypeAdjustment {
  chest: number;
  waist: number;
  hips: number;
  shoulder: number;
}

const BODY_TYPE_ADJUSTMENTS: Record<
  "slim" | "regular" | "athletic" | "plus",
  BodyTypeAdjustment
> = {
  slim: { chest: -0.05, waist: -0.05, hips: -0.04, shoulder: -0.02 },
  regular: { chest: 0, waist: 0, hips: 0, shoulder: 0 },
  athletic: { chest: 0.05, waist: -0.05, hips: -0.02, shoulder: 0.04 },
  plus: { chest: 0.08, waist: 0.10, hips: 0.10, shoulder: 0.04 },
};

// ---------------------------------------------------------------------------
// Canonical measurement column name patterns
// Used to map chart headers to measurement types
// ---------------------------------------------------------------------------

const MEASUREMENT_PATTERNS: Record<string, RegExp> = {
  chest: /chest|bust|torso/i,
  waist: /waist/i,
  hips: /hip/i,
  shoulder: /shoulder/i,
  armLength: /arm.?length|sleeve/i,
  inseam: /inseam|inside.?leg/i,
  height: /height|stature/i,
};

// ---------------------------------------------------------------------------
// Estimate body measurements from height, weight, gender, body type
// ---------------------------------------------------------------------------

export function estimateMeasurements(
  height: number,
  weight: number,
  gender: "male" | "female",
  bodyType: "slim" | "regular" | "athletic" | "plus",
): Record<string, number> {
  const p = PROPORTIONS[gender];
  const adj = BODY_TYPE_ADJUSTMENTS[bodyType];

  const bmi = weight / ((height / 100) ** 2);
  const bmiDelta = bmi - 22;

  const chest =
    height * p.chestBase + bmiDelta * p.bmiFactor * (1 + adj.chest);
  const waist =
    height * p.waistBase + bmiDelta * p.bmiFactor * (1 + adj.waist);
  const hips =
    height * p.hipsBase + bmiDelta * p.bmiFactor * (1 + adj.hips);
  const shoulder =
    height * p.shoulderBase * (1 + adj.shoulder);
  const armLength = height * p.armLengthBase;
  const inseam = height * p.inseamBase;

  return {
    chest: Math.round(chest * 10) / 10,
    waist: Math.round(waist * 10) / 10,
    hips: Math.round(hips * 10) / 10,
    shoulder: Math.round(shoulder * 10) / 10,
    armLength: Math.round(armLength * 10) / 10,
    inseam: Math.round(inseam * 10) / 10,
    height,
  };
}

// ---------------------------------------------------------------------------
// Parse a measurement value from a chart cell.
// Handles plain numbers ("34"), ranges ("32-34"), values with units ("34 cm"),
// and fractional values ("34.5").
// Returns the numeric midpoint in cm (or the plain value if no range).
// ---------------------------------------------------------------------------

function parseMeasurementValue(raw: string): number | null {
  if (!raw || raw.trim() === "" || raw.trim() === "-") return null;

  // Strip units and extra whitespace
  const cleaned = raw.replace(/\s*(cm|in|inches?|")\s*/gi, "").trim();

  // Range pattern: "32-34" or "32–34" (en-dash)
  const rangeMatch = cleaned.match(/^(\d+(?:\.\d+)?)\s*[-–]\s*(\d+(?:\.\d+)?)$/);
  if (rangeMatch) {
    const lo = parseFloat(rangeMatch[1]);
    const hi = parseFloat(rangeMatch[2]);
    return (lo + hi) / 2;
  }

  // Plain number
  const num = parseFloat(cleaned);
  return isNaN(num) ? null : num;
}

// ---------------------------------------------------------------------------
// Identify the size label column (the column that holds "S", "M", "L", etc.)
// Returns the header key most likely to be the size label, or the first key.
// ---------------------------------------------------------------------------

function findSizeColumnKey(headers: string[]): string {
  const sizePattern = /^size$/i;
  const found = headers.find((h) => sizePattern.test(h.trim()));
  return found ?? headers[0];
}

// ---------------------------------------------------------------------------
// Map a chart header to a canonical measurement type key.
// Returns null if no match found.
// ---------------------------------------------------------------------------

function headerToMeasurementKey(header: string): string | null {
  for (const [key, pattern] of Object.entries(MEASUREMENT_PATTERNS)) {
    if (pattern.test(header)) return key;
  }
  return null;
}

// ---------------------------------------------------------------------------
// Compute Euclidean distance between estimated measurements and a chart row.
// Only the measurements present in both sets are compared.
// Returns { distance, matchedFields } where matchedFields is how many
// measurement columns contributed to the score.
// ---------------------------------------------------------------------------

function scoreRow(
  estimated: Record<string, number>,
  row: Record<string, string>,
  headers: string[],
): { distance: number; matchedFields: number } {
  let sumSquares = 0;
  let matchedFields = 0;

  for (const header of headers) {
    const measurementKey = headerToMeasurementKey(header);
    if (!measurementKey) continue;

    const estimatedValue = estimated[measurementKey];
    if (estimatedValue === undefined) continue;

    const rawCell = row[header];
    if (!rawCell) continue;

    const chartValue = parseMeasurementValue(rawCell);
    if (chartValue === null) continue;

    const diff = estimatedValue - chartValue;
    sumSquares += diff * diff;
    matchedFields++;
  }

  if (matchedFields === 0) return { distance: Infinity, matchedFields: 0 };
  return { distance: Math.sqrt(sumSquares / matchedFields), matchedFields };
}

// ---------------------------------------------------------------------------
// Convert a distance (cm) to a 0–100 confidence score.
// Distance of 0 → 100, distance of 10 cm → ~50, distance >= 20 → near 0.
// Uses an exponential decay: confidence = 100 * exp(-distance / 7)
// ---------------------------------------------------------------------------

function distanceToConfidence(distance: number): number {
  if (!isFinite(distance)) return 0;
  const raw = 100 * Math.exp(-distance / 7);
  return Math.round(Math.min(100, Math.max(0, raw)));
}

// ---------------------------------------------------------------------------
// Main recommendation function
// ---------------------------------------------------------------------------

export function recommendSize(input: RecommendInput): RecommendResult {
  const { height, weight, gender, bodyType, chartData } = input;

  const estimated = estimateMeasurements(height, weight, gender, bodyType);
  const { headers, rows } = chartData;

  if (!headers.length || !rows.length) {
    return {
      recommendedSize: "",
      confidence: 0,
      alternatives: [],
      estimatedMeasurements: estimated,
    };
  }

  const sizeKey = findSizeColumnKey(headers);

  // Score every row
  const scored = rows
    .map((row) => {
      const sizeLabel = (row[sizeKey] ?? "").trim();
      if (!sizeLabel) return null;

      const { distance, matchedFields } = scoreRow(estimated, row, headers);

      // Penalise rows with too few matching measurement fields
      const adjustedDistance =
        matchedFields === 0 ? Infinity : distance * (1 + 0.1 / matchedFields);

      return { size: sizeLabel, distance: adjustedDistance, matchedFields };
    })
    .filter(
      (
        r,
      ): r is { size: string; distance: number; matchedFields: number } =>
        r !== null && isFinite(r.distance),
    )
    .sort((a, b) => a.distance - b.distance);

  if (!scored.length) {
    return {
      recommendedSize: "",
      confidence: 0,
      alternatives: [],
      estimatedMeasurements: estimated,
    };
  }

  const best = scored[0];
  const alternatives = scored
    .slice(1, 4)
    .map((r) => ({
      size: r.size,
      confidence: distanceToConfidence(r.distance),
    }))
    .filter((r) => r.confidence > 5);

  return {
    recommendedSize: best.size,
    confidence: distanceToConfidence(best.distance),
    alternatives,
    estimatedMeasurements: estimated,
  };
}

// ---------------------------------------------------------------------------
// Shopify Billing Integration — Subscription lifecycle management
// Uses Shopify Admin GraphQL API (2026-01)
// ---------------------------------------------------------------------------

import db from "~/db.server";
import { PLANS, getPlan } from "~/lib/plans";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface BillingContext {
  admin: { graphql: (query: string, options?: { variables?: Record<string, unknown> }) => Promise<{ json: () => Promise<unknown> }> };
  session: { shop: string };
}

interface AppSubscriptionCreateResponse {
  data: {
    appSubscriptionCreate: {
      appSubscription: { id: string } | null;
      confirmationUrl: string | null;
      userErrors: { field: string; message: string }[];
    };
  };
}

interface AppSubscriptionCancelResponse {
  data: {
    appSubscriptionCancel: {
      appSubscription: { id: string; status: string } | null;
      userErrors: { field: string; message: string }[];
    };
  };
}

interface CurrentAppInstallationResponse {
  data: {
    currentAppInstallation: {
      activeSubscriptions: {
        id: string;
        name: string;
        status: string;
        createdAt: string;
        currentPeriodEnd: string | null;
        test: boolean;
        lineItems: {
          plan: {
            pricingDetails:
              | { price: { amount: string; currencyCode: string } }
              | { interval: string; base: { amount: string; currencyCode: string } };
          };
        }[];
      }[];
    };
  };
}

export interface ActiveShopifySubscription {
  id: string;
  name: string;
  status: string;
  createdAt: string;
  currentPeriodEnd: string | null;
  test: boolean;
}

// ---------------------------------------------------------------------------
// GraphQL documents
// ---------------------------------------------------------------------------

const APP_SUBSCRIPTION_CREATE_MUTATION = `
  mutation appSubscriptionCreate(
    $name: String!
    $lineItems: [AppSubscriptionLineItemInput!]!
    $returnUrl: URL!
    $test: Boolean
  ) {
    appSubscriptionCreate(
      name: $name
      lineItems: $lineItems
      returnUrl: $returnUrl
      test: $test
    ) {
      appSubscription {
        id
      }
      confirmationUrl
      userErrors {
        field
        message
      }
    }
  }
`;

const APP_SUBSCRIPTION_CANCEL_MUTATION = `
  mutation appSubscriptionCancel($id: ID!) {
    appSubscriptionCancel(id: $id) {
      appSubscription {
        id
        status
      }
      userErrors {
        field
        message
      }
    }
  }
`;

const CURRENT_APP_INSTALLATION_QUERY = `
  query currentAppInstallation {
    currentAppInstallation {
      activeSubscriptions {
        id
        name
        status
        createdAt
        currentPeriodEnd
        test
        lineItems {
          plan {
            pricingDetails {
              ... on AppRecurringPricing {
                price {
                  amount
                  currencyCode
                }
                interval
              }
              ... on AppUsagePricing {
                cappedAmount {
                  amount
                  currencyCode
                }
                terms
              }
            }
          }
        }
      }
    }
  }
`;

// ---------------------------------------------------------------------------
// createSubscription
// Creates a Shopify app subscription and returns the hosted confirmation URL.
// The merchant must visit confirmationUrl to approve the charge.
// ---------------------------------------------------------------------------

export async function createSubscription(
  context: BillingContext,
  planId: string,
  billingInterval: "monthly" | "annual",
): Promise<{ confirmationUrl: string; subscriptionId: string }> {
  const plan = getPlan(planId);

  if (plan.id === "free") {
    throw new Error("Free plan does not require a Shopify subscription.");
  }

  const price = billingInterval === "annual" ? plan.annualPrice : plan.price;
  const interval = billingInterval === "annual" ? "ANNUAL" : "EVERY_30_DAYS";
  const planName = `Size Chart & Recommender — ${plan.name} (${billingInterval})`;

  const returnUrl = `https://${context.session.shop}/admin/apps`;

  const response = await context.admin.graphql(APP_SUBSCRIPTION_CREATE_MUTATION, {
    variables: {
      name: planName,
      lineItems: [
        {
          plan: {
            appRecurringPricingDetails: {
              price: { amount: price, currencyCode: "USD" },
              interval,
            },
          },
        },
      ],
      returnUrl,
      test: process.env.NODE_ENV !== "production",
    },
  });

  const body = (await response.json()) as AppSubscriptionCreateResponse;
  const result = body.data.appSubscriptionCreate;

  if (result.userErrors.length > 0) {
    const messages = result.userErrors.map((e) => e.message).join(", ");
    throw new Error(`Shopify billing error: ${messages}`);
  }

  if (!result.confirmationUrl || !result.appSubscription) {
    throw new Error("Shopify did not return a confirmation URL.");
  }

  // Persist a pending subscription record in local DB
  await db.subscription.upsert({
    where: { shop: context.session.shop },
    create: {
      shop: context.session.shop,
      planId,
      billingInterval,
      shopifySubscriptionId: result.appSubscription.id,
      status: "pending",
    },
    update: {
      planId,
      billingInterval,
      shopifySubscriptionId: result.appSubscription.id,
      status: "pending",
    },
  });

  return {
    confirmationUrl: result.confirmationUrl,
    subscriptionId: result.appSubscription.id,
  };
}

// ---------------------------------------------------------------------------
// cancelSubscription
// Cancels the merchant's current active Shopify subscription.
// ---------------------------------------------------------------------------

export async function cancelSubscription(
  context: BillingContext,
): Promise<void> {
  const existing = await db.subscription.findUnique({
    where: { shop: context.session.shop },
  });

  if (!existing?.shopifySubscriptionId) {
    throw new Error("No active subscription found to cancel.");
  }

  const response = await context.admin.graphql(APP_SUBSCRIPTION_CANCEL_MUTATION, {
    variables: { id: existing.shopifySubscriptionId },
  });

  const body = (await response.json()) as AppSubscriptionCancelResponse;
  const result = body.data.appSubscriptionCancel;

  if (result.userErrors.length > 0) {
    const messages = result.userErrors.map((e) => e.message).join(", ");
    throw new Error(`Shopify cancel error: ${messages}`);
  }

  // Mark subscription as cancelled in local DB
  await db.subscription.update({
    where: { shop: context.session.shop },
    data: {
      status: "cancelled",
      planId: "free",
      shopifySubscriptionId: null,
    },
  });
}

// ---------------------------------------------------------------------------
// getActiveSubscription
// Fetches the merchant's current active subscription from Shopify.
// Returns null when on the free plan (no active charge).
// ---------------------------------------------------------------------------

export async function getActiveSubscription(
  context: BillingContext,
): Promise<ActiveShopifySubscription | null> {
  const response = await context.admin.graphql(CURRENT_APP_INSTALLATION_QUERY);
  const body = (await response.json()) as CurrentAppInstallationResponse;

  const subs =
    body.data.currentAppInstallation.activeSubscriptions;

  if (!subs || subs.length === 0) return null;

  // Prefer ACTIVE status; fall back to first entry
  const active =
    subs.find((s) => s.status === "ACTIVE") ?? subs[0];

  return {
    id: active.id,
    name: active.name,
    status: active.status,
    createdAt: active.createdAt,
    currentPeriodEnd: active.currentPeriodEnd,
    test: active.test,
  };
}

// ---------------------------------------------------------------------------
// syncSubscription
// Reconciles Shopify subscription status with the local DB record.
// Intended to be called from webhook handlers.
// ---------------------------------------------------------------------------

export async function syncSubscription(
  shop: string,
  shopifySubscriptionId: string,
  shopifyStatus: string,
): Promise<void> {
  const normalizedStatus = shopifyStatus.toLowerCase();

  // Map Shopify statuses to local statuses
  const statusMap: Record<string, string> = {
    active: "active",
    cancelled: "cancelled",
    declined: "cancelled",
    expired: "cancelled",
    frozen: "frozen",
    pending: "pending",
  };

  const localStatus = statusMap[normalizedStatus] ?? "pending";

  // Resolve planId from the subscription name stored in the local record
  const existing = await db.subscription.findFirst({
    where: { shop, shopifySubscriptionId },
  });

  const resolvedPlanId = (() => {
    if (localStatus === "cancelled") return "free";
    if (existing?.planId) return existing.planId;
    // Attempt to match by subscription name if we have no local record
    for (const plan of PLANS) {
      if (
        existing?.planId === plan.id ||
        shopifySubscriptionId.includes(plan.id)
      ) {
        return plan.id;
      }
    }
    return "free";
  })();

  await db.subscription.upsert({
    where: { shop },
    create: {
      shop,
      planId: resolvedPlanId,
      billingInterval: existing?.billingInterval ?? "monthly",
      shopifySubscriptionId,
      status: localStatus,
    },
    update: {
      shopifySubscriptionId,
      status: localStatus,
      ...(localStatus === "cancelled" ? { planId: "free" } : {}),
    },
  });
}

// ---------------------------------------------------------------------------
// getLocalSubscription
// Reads the shop's subscription record from the local DB.
// Returns a default free-plan record if none exists.
// ---------------------------------------------------------------------------

export async function getLocalSubscription(shop: string) {
  const record = await db.subscription.findUnique({ where: { shop } });

  if (!record) {
    return {
      shop,
      planId: "free",
      billingInterval: "monthly" as const,
      shopifySubscriptionId: null,
      status: "active",
      trialEndsAt: null,
    };
  }

  return record;
}

// ---------------------------------------------------------------------------
// Analytics Aggregation — server-side helpers for the analytics dashboard
// All queries are scoped by `shop` (security requirement)
// ---------------------------------------------------------------------------

import db from "~/db.server";

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

export interface DateRange {
  from: Date;
  to: Date;
}

export interface AnalyticsSummary {
  totalViews: number;
  totalClicks: number;
  totalRecommendations: number;
  totalConversions: number;
  totalDismissals: number;
}

export interface ConversionFunnel {
  viewCount: number;
  clickRate: number; // clicks / views (0–1)
  recommendRate: number; // recommends / views (0–1)
  convertRate: number; // converts / views (0–1)
}

export interface ChartPerformance {
  sizeChartId: string;
  name: string;
  views: number;
  clicks: number;
  recommendations: number;
  conversions: number;
}

export interface DailyDataPoint {
  date: string; // ISO date string "YYYY-MM-DD"
  count: number;
}

export interface ProductPerformance {
  productId: string;
  views: number;
  clicks: number;
  recommendations: number;
  conversions: number;
}

// ---------------------------------------------------------------------------
// getAnalyticsSummary
// Returns totals for each event type within the given date range.
// ---------------------------------------------------------------------------

export async function getAnalyticsSummary(
  shop: string,
  dateRange: DateRange,
): Promise<AnalyticsSummary> {
  const where = {
    shop,
    createdAt: { gte: dateRange.from, lte: dateRange.to },
  };

  const [views, clicks, recommendations, conversions, dismissals] =
    await Promise.all([
      db.analyticsEvent.count({ where: { ...where, eventType: "view" } }),
      db.analyticsEvent.count({ where: { ...where, eventType: "click" } }),
      db.analyticsEvent.count({ where: { ...where, eventType: "recommend" } }),
      db.analyticsEvent.count({ where: { ...where, eventType: "convert" } }),
      db.analyticsEvent.count({ where: { ...where, eventType: "dismiss" } }),
    ]);

  return {
    totalViews: views,
    totalClicks: clicks,
    totalRecommendations: recommendations,
    totalConversions: conversions,
    totalDismissals: dismissals,
  };
}

// ---------------------------------------------------------------------------
// getConversionFunnel
// Returns step-level rates so the UI can render a funnel chart.
// ---------------------------------------------------------------------------

export async function getConversionFunnel(
  shop: string,
  dateRange: DateRange,
): Promise<ConversionFunnel> {
  const summary = await getAnalyticsSummary(shop, dateRange);

  const safe = (numerator: number, denominator: number): number => {
    if (denominator === 0) return 0;
    return Math.round((numerator / denominator) * 10000) / 10000; // 4 dp
  };

  return {
    viewCount: summary.totalViews,
    clickRate: safe(summary.totalClicks, summary.totalViews),
    recommendRate: safe(summary.totalRecommendations, summary.totalViews),
    convertRate: safe(summary.totalConversions, summary.totalViews),
  };
}

// ---------------------------------------------------------------------------
// getTopCharts
// Returns top N size charts ordered by view count within the date range.
// Joins with the SizeChart table to include chart names.
// ---------------------------------------------------------------------------

export async function getTopCharts(
  shop: string,
  dateRange: DateRange,
  limit: number = 10,
): Promise<ChartPerformance[]> {
  // Aggregate view events grouped by sizeChartId
  const eventTypes: ("view" | "click" | "recommend" | "convert")[] = [
    "view",
    "click",
    "recommend",
    "convert",
  ];

  const where = {
    shop,
    sizeChartId: { not: null },
    createdAt: { gte: dateRange.from, lte: dateRange.to },
  };

  // Run all four aggregations in parallel
  const [viewGroups, clickGroups, recommendGroups, convertGroups] =
    await Promise.all(
      eventTypes.map((eventType) =>
        db.analyticsEvent.groupBy({
          by: ["sizeChartId"],
          where: { ...where, eventType },
          _count: { id: true },
          orderBy: { _count: { id: "desc" } },
        }),
      ),
    );

  // Build a lookup map: sizeChartId → { views, clicks, recommends, converts }
  type CountMap = Map<string, number>;

  const toMap = (
    groups: { sizeChartId: string | null; _count: { id: number } }[],
  ): CountMap => {
    const m: CountMap = new Map();
    for (const g of groups) {
      if (g.sizeChartId) m.set(g.sizeChartId, g._count.id);
    }
    return m;
  };

  const viewMap = toMap(viewGroups);
  const clickMap = toMap(clickGroups);
  const recommendMap = toMap(recommendGroups);
  const convertMap = toMap(convertGroups);

  // Collect all chart IDs that have at least one view
  const topIds = [...viewMap.entries()]
    .sort((a, b) => b[1] - a[1])
    .slice(0, limit)
    .map(([id]) => id);

  if (topIds.length === 0) return [];

  // Fetch chart names from the DB in a single query
  const charts = await db.sizeChart.findMany({
    where: { shop, id: { in: topIds } },
    select: { id: true, name: true },
  });

  const nameMap = new Map(charts.map((c) => [c.id, c.name]));

  return topIds.map((id) => ({
    sizeChartId: id,
    name: nameMap.get(id) ?? "Deleted chart",
    views: viewMap.get(id) ?? 0,
    clicks: clickMap.get(id) ?? 0,
    recommendations: recommendMap.get(id) ?? 0,
    conversions: convertMap.get(id) ?? 0,
  }));
}

// ---------------------------------------------------------------------------
// getDailyTrend
// Returns daily event counts for the given event type across the date range.
// Used for time-series charts in the analytics dashboard.
// ---------------------------------------------------------------------------

export async function getDailyTrend(
  shop: string,
  dateRange: DateRange,
  eventType: string,
): Promise<DailyDataPoint[]> {
  const events = await db.analyticsEvent.findMany({
    where: {
      shop,
      eventType,
      createdAt: { gte: dateRange.from, lte: dateRange.to },
    },
    select: { createdAt: true },
    orderBy: { createdAt: "asc" },
  });

  // Aggregate counts by calendar date (YYYY-MM-DD)
  const countByDate = new Map<string, number>();

  for (const event of events) {
    const dateKey = event.createdAt.toISOString().slice(0, 10);
    countByDate.set(dateKey, (countByDate.get(dateKey) ?? 0) + 1);
  }

  // Fill in zero-count dates across the full range so charts render correctly
  const result: DailyDataPoint[] = [];
  const cursor = new Date(dateRange.from);
  cursor.setUTCHours(0, 0, 0, 0);
  const end = new Date(dateRange.to);
  end.setUTCHours(23, 59, 59, 999);

  while (cursor <= end) {
    const dateKey = cursor.toISOString().slice(0, 10);
    result.push({ date: dateKey, count: countByDate.get(dateKey) ?? 0 });
    cursor.setUTCDate(cursor.getUTCDate() + 1);
  }

  return result;
}

// ---------------------------------------------------------------------------
// getProductPerformance
// Returns per-product event counts, scoped to a shop and date range.
// Useful for identifying which products benefit most from size charts.
// ---------------------------------------------------------------------------

export async function getProductPerformance(
  shop: string,
  dateRange: DateRange,
): Promise<ProductPerformance[]> {
  const where = {
    shop,
    productId: { not: null },
    createdAt: { gte: dateRange.from, lte: dateRange.to },
  };

  const eventTypes: string[] = ["view", "click", "recommend", "convert"];

  const groups = await Promise.all(
    eventTypes.map((eventType) =>
      db.analyticsEvent.groupBy({
        by: ["productId"],
        where: { ...where, eventType },
        _count: { id: true },
      }),
    ),
  );

  const [viewGroups, clickGroups, recommendGroups, convertGroups] = groups;

  type ProductMap = Map<string, number>;

  const toProductMap = (
    g: { productId: string | null; _count: { id: number } }[],
  ): ProductMap => {
    const m: ProductMap = new Map();
    for (const row of g) {
      if (row.productId) m.set(row.productId, row._count.id);
    }
    return m;
  };

  const viewMap = toProductMap(viewGroups);
  const clickMap = toProductMap(clickGroups);
  const recommendMap = toProductMap(recommendGroups);
  const convertMap = toProductMap(convertGroups);

  // Union of all product IDs across event types
  const allProductIds = new Set<string>([
    ...viewMap.keys(),
    ...clickMap.keys(),
    ...recommendMap.keys(),
    ...convertMap.keys(),
  ]);

  return [...allProductIds]
    .map((productId) => ({
      productId,
      views: viewMap.get(productId) ?? 0,
      clicks: clickMap.get(productId) ?? 0,
      recommendations: recommendMap.get(productId) ?? 0,
      conversions: convertMap.get(productId) ?? 0,
    }))
    .sort((a, b) => b.views - a.views);
}

// ---------------------------------------------------------------------------
// buildDateRange
// Convenience helper: builds a DateRange from a preset string.
// Consumers can use this instead of constructing Date objects manually.
// ---------------------------------------------------------------------------

export function buildDateRange(
  preset: "7d" | "30d" | "90d" | "365d",
): DateRange {
  const to = new Date();
  const from = new Date();

  const days: Record<typeof preset, number> = {
    "7d": 7,
    "30d": 30,
    "90d": 90,
    "365d": 365,
  };

  from.setDate(from.getDate() - days[preset]);
  from.setHours(0, 0, 0, 0);

  return { from, to };
}

